<script setup>
import { computed, ref, watch } from 'vue'
const props=defineProps({source:Object,workspace:Object})
const emit=defineEmits(['refresh','message'])
const count=ref(3),duration=ref(90),style=ref('BALANCED'),platform=ref('竖屏短剧'),region=ref('中国'),compression=ref('MEDIUM'),busy=ref(false),episodes=ref([]),planEstimate=ref(null),scriptEstimate=ref(null),rangeFrom=ref(1),rangeTo=ref(10)
const plans=computed(()=>(props.workspace?.['adaptation-plans']||[]).filter(item=>item.novelId===props.source?.id).sort((a,b)=>b.version-a.version))
const current=computed(()=>plans.value[0])
async function json(path,options={}){const response=await fetch('/api'+path,{headers:{'Content-Type':'application/json'},...options});const body=await response.json();if(!response.ok)throw new Error(body.message||'操作失败');return body}
async function load(){if(!current.value){episodes.value=[];return}try{episodes.value=(await json(`/adaptation-plans/${current.value.id}/episodes`)).map(item=>({...item,sourceChapterText:(item.sourceChapterIds||[]).join(', '),sourceChunkText:(item.sourceChunkIds||[]).join(', ')}))}catch(error){emit('message',error.message,true)}}
watch(()=>current.value?.id,load,{immediate:true})
const config=()=>({projectId:props.source.projectId,targetEpisodeCount:Number(count.value),targetEpisodeDuration:Number(duration.value),adaptationStyle:style.value,platform:platform.value,region:region.value,compressionLevel:compression.value,createdBy:'USER'})
const limits=estimate=>({maxRequests:estimate.estimatedRequests||1,maxInputTokens:estimate.estimatedInputTokens||1,maxOutputTokens:estimate.estimatedOutputTokens||1,maxEstimatedCost:estimate.estimatedCost||0})
async function estimatePlan(){busy.value=true;try{planEstimate.value=await json(`/novels/${props.source.id}/adaptation-plans/estimate`,{method:'POST',body:JSON.stringify(config())})}catch(error){emit('message',error.message,true)}finally{busy.value=false}}
async function create(){if(!planEstimate.value)await estimatePlan();if(!planEstimate.value||!confirm(`预计 ${planEstimate.value.estimatedRequests} 次文本请求。确认预算并生成改编计划？`))return;busy.value=true;try{await json(`/novels/${props.source.id}/adaptation-plans`,{method:'POST',body:JSON.stringify({...config(),confirmed:true,liveConfirmed:true,budget:limits(planEstimate.value)})});emit('message','改编计划已生成，请逐集审查');emit('refresh')}catch(error){emit('message',error.message,true)}finally{busy.value=false}}
async function save(episode){busy.value=true;try{const ids=value=>value.split(',').map(item=>item.trim()).filter(Boolean);await json(`/adaptation-plans/${current.value.id}/episodes/${episode.episodeNo}`,{method:'PATCH',body:JSON.stringify({revision:current.value.revision,episodePlanRevision:episode.revision,sourceChapterIds:ids(episode.sourceChapterText),sourceChunkIds:ids(episode.sourceChunkText),episodeGoal:episode.episodeGoal,openingHook:episode.openingHook,centralConflict:episode.centralConflict,climax:episode.climax,endingHook:episode.endingHook,createdBy:'USER'})});emit('message',`第 ${episode.episodeNo} 集已建立新计划版本，仅复核相邻集`);emit('refresh')}catch(error){emit('message',error.message,true)}finally{busy.value=false}}
async function confirm(){busy.value=true;try{await json(`/adaptation-plans/${current.value.id}/confirm`,{method:'POST',body:JSON.stringify({revision:current.value.revision})});emit('message','改编计划已确认，可以进入分集剧本');emit('refresh')}catch(error){emit('message',error.message,true)}finally{busy.value=false}}
async function estimateScripts(mode='RANGE',from=rangeFrom.value,to=rangeTo.value){scriptEstimate.value=await json(`/adaptation-plans/${current.value.id}/scripts/estimate`,{method:'POST',body:JSON.stringify({mode,fromEpisode:Number(from),toEpisode:Number(to),contextBudgetChars:12000})});return scriptEstimate.value}
async function generateBatch(mode='RANGE',from=rangeFrom.value,to=rangeTo.value){busy.value=true;try{const estimate=await estimateScripts(mode,from,to);if(!estimate.pendingEpisodes){emit('message','没有待生成的分集');return}if(!confirm(`将逐集生成 ${estimate.pendingEpisodes} 集，失败时保留已完成集。确认开始？`))return;const result=await json(`/adaptation-plans/${current.value.id}/scripts`,{method:'POST',body:JSON.stringify({mode,fromEpisode:Number(from),toEpisode:Number(to),contextBudgetChars:12000,confirmed:true,liveConfirmed:true,budget:limits(estimate)})});emit('message',result.status==='SUCCEEDED'?`已生成 ${result.completedEpisodes} 集待审剧本`:`第 ${result.failedEpisodeNo} 集失败，前 ${result.completedEpisodes} 集已保留`,result.status!=='SUCCEEDED');emit('refresh')}catch(error){emit('message',error.message,true)}finally{busy.value=false}}
async function generateScript(episode){await generateBatch('SINGLE',episode.episodeNo,episode.episodeNo)}
</script>
<template><section class="panel"><span class="eyebrow">分集改编</span><h3>可审查的改编计划</h3><p>章节与集数可以多对多映射。每集锁定来源、知识边界和未来保留事实。</p><div class="button-row"><label>目标集数 <input v-model.number="count" type="number" min="1"/></label><label>单集秒数 <input v-model.number="duration" type="number" min="10"/></label><label>改编方式 <select v-model="style"><option>FAITHFUL</option><option>BALANCED</option><option>SHORT_DRAMA</option></select></label><label>平台 <input v-model="platform"/></label><label>地区 <input v-model="region"/></label><label>压缩程度 <select v-model="compression"><option>LOW</option><option>MEDIUM</option><option>HIGH</option></select></label><button :disabled="busy" @click="estimatePlan">估算文本请求</button><button class="primary" :disabled="busy" @click="create">确认预算并生成计划</button></div><p v-if="planEstimate">预计 {{planEstimate.estimatedRequests}} 次请求 · 输入 {{planEstimate.estimatedInputTokens}} tokens · 输出 {{planEstimate.estimatedOutputTokens}} tokens · {{planEstimate.pricingStatus}}</p><div v-if="current"><p><b>v{{current.version}}</b> · {{current.status}} · 覆盖 {{Math.round((current.coverage?.coverageRatio||0)*100)}}%</p><p>目标 {{current.targetEpisodeCount}} 集 × {{current.targetEpisodeDuration}} 秒 · {{current.adaptationStyle}} · {{current.platform}} / {{current.region}} · 压缩 {{current.compressionLevel}}</p><p v-if="current.continuityIssues?.length" class="error">有 {{current.continuityIssues.length}} 个相邻集状态冲突，修正后才能确认。</p><div v-if="current.status==='CONFIRMED'" class="panel"><h4>逐集编剧</h4><div class="button-row"><label>从第 <input v-model.number="rangeFrom" type="number" min="1"/></label><label>到第 <input v-model.number="rangeTo" type="number" min="1"/></label><button :disabled="busy" @click="generateBatch('RANGE')">生成所选范围</button><button :disabled="busy" @click="generateBatch('ALL_UNSTARTED',1,episodes.length)">生成全部未生成集</button></div><p v-if="scriptEstimate">待生成 {{scriptEstimate.pendingEpisodes}} 集 · 预计 {{scriptEstimate.estimatedRequests}} 次请求 · {{scriptEstimate.pricingStatus}}</p></div><article v-for="episode in episodes" :key="episode.id" class="panel"><h4>第 {{episode.episodeNo}} 集</h4><p>来源章节：{{episode.sourceChapterIds?.join('、')}} · 目标时长 {{episode.estimatedDurationSec}} 秒</p><label>来源章节 ID（逗号分隔）<textarea v-model="episode.sourceChapterText"/></label><label>来源片段 ID（逗号分隔）<textarea v-model="episode.sourceChunkText"/></label><label>本集目标<textarea v-model="episode.episodeGoal"/></label><label>开场钩子<textarea v-model="episode.openingHook"/></label><label>核心冲突<textarea v-model="episode.centralConflict"/></label><label>信息揭示<textarea v-model="episode.informationReveal"/></label><label>高潮<textarea v-model="episode.climax"/></label><label>结尾钩子<textarea v-model="episode.endingHook"/></label><div class="button-row"><button :disabled="busy||current.status==='CONFIRMED'" @click="save(episode)">保存为新版本</button><button v-if="current.status==='CONFIRMED'" class="primary" :disabled="busy" @click="generateScript(episode)">只生成本集待审剧本</button></div></article><button class="primary" :disabled="busy||current.status==='CONFIRMED'||current.continuityIssues?.length" @click="confirm">确认改编计划</button></div></section></template>
